import {tax,RULES} from './engine.js?v=11';
export const COMP_DEFAULTS={age:40,years:20,own:2000,employer:1000,salary:35000,otherOwn:0,otherEmployer:0,otherSales:0,inflation:2.5,pensioner:0,dipRate:8,dpsRate:8,dipEntry:3,dipFee:2.16,dpsEntry:0,dpsFee:1,dpsPerformance:15,netReturns:0,loyalty:0,loyaltyRate:0,dipTax:'test',payout:'lump'};
export function cleanComparison(raw={}){const s={...COMP_DEFAULTS};for(const k in s){if(['dipTax','payout'].includes(k))continue;const n=Number(raw[k]??s[k]);if(Number.isFinite(n))s[k]=n;}const limits={age:[18,90],years:[1,50],own:[0,100000],employer:[0,100000],salary:[0,1000000],otherOwn:[0,48000],otherEmployer:[0,1000000],otherSales:[0,1000000000],inflation:[0,30],dipRate:[-100,100],dpsRate:[-100,100],dipEntry:[0,100],dpsEntry:[0,100],dipFee:[0,20],dpsFee:[0,20],dpsPerformance:[0,50],netReturns:[0,1],pensioner:[0,1],loyalty:[0,1],loyaltyRate:[0,20]};for(const [k,[a,b]] of Object.entries(limits))s[k]=Math.min(b,Math.max(a,s[k]));for(const k of ['age','years','netReturns','pensioner','loyalty'])s[k]=Math.round(s[k]);s.dipTax=['test','exempt','taxable'].includes(raw.dipTax)?raw.dipTax:'test';s.payout=raw.payout==='pension'?'pension':'lump';return s;}
export function compare(raw){const s=cleanComparison(raw),eligible=s.years>=10&&s.age+s.years>=60,available=Math.max(0,48000-s.otherOwn),excess=Math.max(0,s.employer*12-Math.max(0,50000-s.otherEmployer));
 const base=s.salary*12+Math.max(0,s.otherEmployer-50000)+excess-s.otherOwn;
 const incomeTax=amount=>Math.max(0,Math.min(Math.max(0,amount),RULES.threshold)*.15+Math.max(0,amount-RULES.threshold)*.23-RULES.taxCredit);
 const savings=deduct=>tax(base)-tax(base-Math.min(available,deduct));
 const annualTax={dip:savings(s.own*12),dps:savings(Math.max(0,s.own-(s.pensioner?0:1700))*12)};
 const support=s.pensioner||s.own<500?0:Math.min(340,s.own*.2),points=[{year:0,dip:0,dps:0,dipReal:0,dpsReal:0}];
 const run=kind=>{const state=kind==='dps'?support:0,entry=s[kind+'Entry']/100,fee=s.netReturns?0:s[kind+'Fee']/100,performance=s.netReturns||kind==='dip'?0:s.dpsPerformance/100,m=Math.pow(1+s[kind+'Rate']/100,1/12)-1;let v=0,entryCosts=0,management=0,perf=0,annualProfit=0;const cohorts=[],rows=[];
 for(let month=1;month<=s.years*12;month++){const growth=v*m,cost=(v+growth)*fee/12,factor=(1+m)*(1-fee/12);v=Math.max(0,v*factor);for(const c of cohorts)c.value*=factor;management+=cost;annualProfit+=growth-cost;const e=(s.own+s.employer)*entry,deposit=s.own+s.employer+state-e;entryCosts+=e;v+=deposit;cohorts.push({month,value:deposit,cost:s.own+s.employer+state});
 if(month%12===0){const p=Math.min(v,Math.max(0,annualProfit)*performance);v-=p;perf+=p;annualProfit=0;const year=month/12,own=s.own*month,employer=s.employer*month,government=state*month,paid=own+employer+government;
 let taxableGain=Math.max(0,v-paid);if(kind==='dip'&&s.dipTax==='exempt')taxableGain=0;if(kind==='dip'&&s.dipTax==='test')taxableGain=v+s.otherSales<=100000?0:Math.max(0,cohorts.filter(c=>month-c.month<=36).reduce((a,c)=>a+c.value-c.cost,0));
 const dipBase=base-Math.min(available,s.own*12),exitTax=kind==='dps'?(s.payout==='pension'?0:taxableGain*.15):incomeTax(dipBase+taxableGain)-incomeTax(dipBase),net=v-exitTax,taxSaving=annualTax[kind]*year,total=net+taxSaving;
 rows.push({year,value:v,own,employer,state:government,gain:v-paid,entry:entryCosts,management,performance:perf,fees:entryCosts+management+perf,tax:exitTax,net,taxSaving,total,real:total/Math.pow(1+s.inflation/100,year),taxableGain});}
 }return {rows,end:rows.at(-1)};};
 const dip=run('dip'),dps=run('dps');for(let i=0;i<s.years;i++)points.push({year:i+1,dip:dip.rows[i].total,dps:dps.rows[i].total,dipReal:dip.rows[i].total/Math.pow(1+s.inflation/100,i+1),dpsReal:dps.rows[i].total/Math.pow(1+s.inflation/100,i+1)});
 let loyalty=0,previousManagement=0;for(const row of dps.rows){loyalty*=1+Math.max(0,s.loyaltyRate)/100;if(s.age+row.year<=65)loyalty+=(row.management-previousManagement)*.25;previousManagement=row.management;}
 return {s,dip,dps,points,annualTax,support,eligible,excess,loyalty:s.loyalty&&!s.netReturns?loyalty:0,loyaltyEligible:eligible&&s.age+s.years>=65,difference:dip.end.total-dps.end.total};}
